<?php
namespace App\Jobs;
use App\Contracts\Infrastructure\ServerExecutorInterface;use App\Models\DockerImage;use App\Services\Operations\OperationsLogService;use App\Support\RemoteShell;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Queue\Queueable;
class CheckImageUpdatesJob implements ShouldQueue{use Queueable;public function __construct(public ?int $tenantId=null){$this->onQueue(config('infrastructure.queues.monitoring'));}public function handle(ServerExecutorInterface $executor,OperationsLogService $logs):void{$query=DockerImage::with('server')->whereNotNull('tag');if($this->tenantId)$query->where('tenant_id',$this->tenantId);$query->each(function($image)use($executor,$logs){if(config('infrastructure.driver')==='fake')$available=$image->tag==='latest'&&$image->pulled_at?->lt(now()->subHours(12));else{$digest=trim($executor->execute($image->server,'docker manifest inspect '.RemoteShell::quote($image->repository.':'.$image->tag).' 2>/dev/null | sha256sum'));$available=$digest&&$image->digest&&!str_contains($digest,$image->digest);}$image->update(['update_available'=>$available]);if($available)$logs->write($image->tenant_id,'container','info','Update available for '.$image->repository.':'.$image->tag,['server_id'=>$image->server_id,'source'=>'image-scanner']);});}}
